1:  dualpi2_dequeue(lq, cq, pkt) {     % L4SとClassicのキューを結合
2:    while ( lq.byt() + cq.byt() > 0 ) {
3:      if ( scheduler() == lq ) {
4:        lq.dequeue(pkt)                      % スケジューラーがlqを選択
5:        p'_L = laqm(lq.time())                        % ネイティブLAQM
6:        p_L = max(p'_L, p_CL)                  % 結合関数
7:        if ( recur(lq, p_L) )                      % 線形マーキング
8:          mark(pkt)
9:      } else {
10:       cq.dequeue(pkt)                      % スケジューラーがcqを選択
11:       if ( recur(cq, p_C) ) {            % 確率p_C = p'^2
12:         if ( ecn(pkt) == 0 ) {           % ECNフィールド = not-ECTの場合
13:           drop(pkt)                                % 2乗のドロップ
14:           continue        % whileループの先頭に戻る
15:         }
16:         mark(pkt)                                  % 2乗のマーキング
17:       }
18:     }
19:     return(pkt)                      % パケットを返して終了
20:   }
21:   return(NULL)                             % デキューするパケットなし
22: }

23: recur(q, likelihood) {   % ある可能性でTRUEを返す
24:   q.count += likelihood
25:   if (q.count > 1) {
26:     q.count -= 1
27:     return TRUE
28:   }
29:   return FALSE
30: }

1:  cred_dequeue(lq, cq, pkt) {       % L4SとClassicのキューを結合
2:    while ( lq.byt() + cq.byt() > 0 ) {
3:      if ( scheduler() == lq ) {
4:        lq.dequeue(pkt)                            % L4Sをスケジューリング
5a:       p_CL = (Q_C - minTh) / range_L
5b:       if (  ( lq.time() > T )
5c:          OR ( p_CL > maxrand(U) ) )
6:          mark(pkt)
7:      } else {
8:        cq.dequeue(pkt)                        % Classicをスケジューリング
9a:       Q_C = gamma * cq.time() + (1-gamma) * Q_C % ClassicキューのEWMA
10a:      sqrt_p_C = (Q_C - minTh) / range_C
10b:      if ( sqrt_p_C > maxrand(2*U) ) {
11:         if ( (ecn(pkt) == 0)  {            % ECNフィールド = not-ECT
12:           drop(pkt)                    % 2乗のドロップ、ループをやり直す
13:           continue       % whileループの先頭に戻る
14:         }
15:         mark(pkt)
16:       }
17:     }
18:     return(pkt)                % パケットを返してここで終了
19:   }
20:   return(NULL)                            % デキューするパケットなし
21: }

22: maxrand(u) {                % u個の乱数の最大値を返す
23:   maxr=0
24:   while (u-- > 0)
25:     maxr = max(maxr, rand())                   % 0 <= rand() < 1
26:   return(maxr)
27: }

28: scheduler() {
29:   if ( lq.time() + tshift >= cq.time() )
30:     return lq;
31:   else
32:     return cq;
33: }

1:  cred_dequeue(lq, cq, pkt) {       % L4SとClassicのキューを結合
2:    while ( lq.byt() + cq.byt() > 0 ) {
3:      if ( scheduler() == lq ) {
4:        lq.dequeue(pkt)                            % L4Sをスケジューリング
5:        if ((lq.time() > T) OR (Q_C >> (S_L-2) > maxrand(U)))
6:          mark(pkt)
7:      } else {
8:        cq.dequeue(pkt)                        % Classicをスケジューリング
9:        Q_C += (qc.ns() - Q_C) >> g_C             % ClassicキューのEWMA
10:       if ( (Q_C >> (S_C-2) ) > maxrand(2*U) ) {
11:         if ( (ecn(pkt) == 0)  {            % ECNフィールド = not-ECT
12:           drop(pkt)                    % 2乗のドロップ、ループをやり直す
13:           continue       % whileループの先頭に戻る
14:         }
15:         mark(pkt)
16:       }
17:     }
18:     return(pkt)                % パケットを返してここで終了
19:   }
20:   return(NULL)                            % デキューするパケットなし
21: }
